mapper.sql:
WHERE 1 = 1

    AND M.CO_CD = #{coCd}


    AND M.EXPEND_DT >= TO_DATE(#{expendDtFrom}, 'YYYY-MM-DD')


    AND M.EXPEND_DT < TO_DATE(#{expendDtTo}, 'YYYY-MM-DD') + 1


    AND M.REQ_DEPT_ID = #{reqDeptId}


    AND M.REQ_ID = #{reqId}


    AND INSTR(',' || M.PMNT_DIV || ',', ',' || #{pmntDiv} || ',') > 0


    AND M.PAY_CLNT_CD = #{payClntCd}


    AND M.EXPEND_STS = #{expendSts}

mapper.insert:
INSERT INTO TB_CM25M01 (
       CO_CD, EXPEND_NO, EXPEND_DT, REQ_DEPT_ID, REQ_ID
     , PMNT_DIV, PAY_DUE_DIV, PAY_DUE_DT, COST_INFO, EXPEND_CONTENTS
     , PAY_CLNT_CD, CURR_CD, PAY_AMT, VAT_YN, ATCH_DOC_DIV, ATCH_DOC_ETC
     , EXPEND_STS, CREAT_ID, CREAT_DTTM, CREAT_PGM
) VALUES (
       #{coCd}, #{expendNo}, TO_DATE(#{expendDt}, 'YYYY-MM-DD'), #{reqDeptId}, #{reqId}
     , #{pmntDiv}, #{payDueDiv}, #{payDueDt}, #{costInfo}, #{expendContents}
     , #{payClntCd}, #{currCd}, #{payAmt}, #{vatYn}, #{atchDocDiv}, #{atchDocEtc}
     , #{expendSts}, #{userId}, SYSDATE, #{pgmId}
)

mapper.update:
UPDATE TB_CM25M01
   SET EXPEND_DT       = TO_DATE(#{expendDt}, 'YYYY-MM-DD')
     , REQ_DEPT_ID     = #{reqDeptId}
     , REQ_ID          = #{reqId}
     , PMNT_DIV        = #{pmntDiv}
     , PAY_DUE_DIV     = #{payDueDiv}
     , PAY_DUE_DT      = #{payDueDt}
     , COST_INFO       = #{costInfo}
     , EXPEND_CONTENTS = #{expendContents}
     , PAY_CLNT_CD     = #{payClntCd}
     , CURR_CD         = #{currCd}
     , PAY_AMT         = #{payAmt}
     , VAT_YN          = #{vatYn}
     , ATCH_DOC_DIV    = #{atchDocDiv}
     , ATCH_DOC_ETC    = #{atchDocEtc}
     , UDT_ID          = #{userId}
     , UDT_DTTM        = SYSDATE
     , UDT_PGM         = #{pgmId}
 WHERE CO_CD = #{coCd}
   AND EXPEND_NO = #{expendNo}

mapper.delete:
DELETE FROM TB_CM25M01
 WHERE CO_CD = #{coCd}
   AND EXPEND_NO = #{expendNo}

DELETE FROM TB_WB20M03
 WHERE CO_CD = #{coCd}
   AND TODO_NO = #{expendNo}
   AND TODO_DIV2_CODE_ID IN ('TODODIV1202', 'TODODIV2202', 'TODODIV1203', 'TODODIV2204')

mapper.select:
SELECT D.IMAGE_FILE_NAME
     , D.IMAGE_FILE_PATH
     , D.IMAGE_FILE_SIZE
  FROM TB_CM25D01 D
 WHERE D.CO_CD = #{coCd}
   AND D.EXPEND_NO = #{expendNo}
   AND D.FILE_KEY = #{fileKey}
   AND D.PAGE_NO = #{pageNo}

mapper.insert:
INSERT INTO TB_CM25D01 (
       CO_CD, EXPEND_NO, FILE_KEY, FILE_TRGT_KEY, PAGE_NO
     , IMAGE_FILE_NAME, IMAGE_FILE_PATH, IMAGE_FILE_SIZE
     , CREAT_ID, CREAT_DTTM, CREAT_PGM
) VALUES (
       #{coCd}, #{expendNo}, #{fileKey}, #{fileTrgtKey}, #{pageNo}
     , #{imageFileName}, #{imageFilePath}, #{imageFileSize}
     , #{userId}, SYSDATE, #{pgmId}
)

mapper.delete:
DELETE FROM TB_CM25D01
 WHERE CO_CD = #{coCd}
   AND EXPEND_NO = #{expendNo}
